"""Shared pieces for the nand2tetris .tst runners.

This module holds everything that is *simulator independent*:

* ``.tst`` script lexing / parsing (comments, ``,``/``;`` separators,
  ``repeat`` / ``while`` blocks, quoted ``echo`` strings),
* value literal parsing (``-1``, ``%B0011``, ``%X2000``, ``%D-5``),
* ``output-list`` column specs, header rendering and value rendering,
* ``.cmp`` loading (CRLF normalisation) and wildcard-aware comparison.

Both the HDL runner (``agent_tests/hdl``) and the assembly runner
(``agent_tests/run_asm_tests.py``) are expected to import from here so the two
never drift apart.
"""

import math
import re

__all__ = [
    'ScriptError', 'Token', 'Cmd', 'Repeat', 'While',
    'strip_comments', 'tokenize', 'parse_script',
    'parse_value', 'Column', 'parse_output_spec', 'parse_output_list',
    'header_cell', 'header_line', 'format_cell', 'render_line',
    'load_cmp', 'line_matches', 'first_mismatch',
]


class ScriptError(Exception):
    pass


# ---------------------------------------------------------------------------
# lexing / parsing of .tst scripts
# ---------------------------------------------------------------------------

_COMMENT_RE = re.compile(r'//[^\n]*|/\*.*?\*/', re.S)
_PUNCT = ',;{}'


def strip_comments(text):
    """Remove ``// ...`` line comments and ``/* ... */`` blocks.

    Replaced with a single space so that ``set a 1// c`` still tokenises.
    """
    return _COMMENT_RE.sub(' ', text)


class Token:
    __slots__ = ('kind', 'text')

    def __init__(self, kind, text):
        self.kind = kind          # 'word' | 'str' | 'punct'
        self.text = text

    def __repr__(self):
        return 'Token(%s,%r)' % (self.kind, self.text)


def tokenize(text):
    """Split already-comment-stripped script text into tokens."""
    toks = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c in _PUNCT:
            toks.append(Token('punct', c))
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while j < n and text[j] != '"':
                buf.append(text[j])
                j += 1
            if j >= n:
                raise ScriptError('unterminated string literal')
            toks.append(Token('str', ''.join(buf)))
            i = j + 1
            continue
        j = i
        while j < n and not text[j].isspace() and text[j] not in _PUNCT \
                and text[j] != '"':
            j += 1
        toks.append(Token('word', text[i:j]))
        i = j
    return toks


class Cmd:
    """A single command: a list of tokens (the terminator is dropped)."""
    __slots__ = ('tokens',)

    def __init__(self, tokens):
        self.tokens = tokens

    @property
    def words(self):
        return [t.text for t in self.tokens]

    @property
    def name(self):
        return self.tokens[0].text.lower() if self.tokens else ''

    def __repr__(self):
        return 'Cmd(%r)' % (self.words,)


class Repeat:
    __slots__ = ('count', 'body')

    def __init__(self, count, body):
        self.count = count        # None == unbounded
        self.body = body

    def __repr__(self):
        return 'Repeat(%r,%r)' % (self.count, self.body)


class While:
    __slots__ = ('lhs', 'op', 'rhs', 'body')

    def __init__(self, lhs, op, rhs, body):
        self.lhs = lhs
        self.op = op
        self.rhs = rhs
        self.body = body

    def __repr__(self):
        return 'While(%r%r%r,%r)' % (self.lhs, self.op, self.rhs, self.body)


_COND_RE = re.compile(r'^\s*(.*?)\s*(<>|<=|>=|=|<|>)\s*(.*?)\s*$')


def parse_script(text):
    """Parse a ``.tst`` script into a list of ``Cmd`` / ``Repeat`` / ``While``."""
    toks = tokenize(strip_comments(text))
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def parse_block(inside_braces):
        nodes = []
        cur = []

        def flush():
            if cur:
                nodes.append(Cmd(list(cur)))
                del cur[:]

        while True:
            t = peek()
            if t is None:
                break
            if t.kind == 'punct':
                if t.text in ',;':
                    pos[0] += 1
                    flush()
                    continue
                if t.text == '}':
                    pos[0] += 1
                    flush()
                    if not inside_braces:
                        raise ScriptError("unexpected '}'")
                    return nodes
                raise ScriptError("unexpected '{'")
            low = t.text.lower()
            if not cur and low == 'repeat':
                pos[0] += 1
                count = None
                nxt = peek()
                if nxt is not None and nxt.kind == 'word' \
                        and re.fullmatch(r'\d+', nxt.text):
                    count = int(nxt.text)
                    pos[0] += 1
                nxt = peek()
                if nxt is None or nxt.kind != 'punct' or nxt.text != '{':
                    raise ScriptError("expected '{' after repeat")
                pos[0] += 1
                nodes.append(Repeat(count, parse_block(True)))
                continue
            if not cur and low == 'while':
                pos[0] += 1
                parts = []
                while True:
                    nxt = peek()
                    if nxt is None:
                        raise ScriptError("expected '{' after while")
                    if nxt.kind == 'punct' and nxt.text == '{':
                        pos[0] += 1
                        break
                    parts.append(nxt.text)
                    pos[0] += 1
                m = _COND_RE.match(' '.join(parts))
                if not m or not m.group(1) or not m.group(3):
                    raise ScriptError('bad while condition: %r'
                                      % ' '.join(parts))
                nodes.append(While(m.group(1).strip(), m.group(2),
                                   m.group(3).strip(), parse_block(True)))
                continue
            cur.append(t)
            pos[0] += 1

        flush()
        if inside_braces:
            raise ScriptError("missing '}'")
        return nodes

    return parse_block(False)


# ---------------------------------------------------------------------------
# value literals
# ---------------------------------------------------------------------------

def parse_value(text, width=16):
    """Parse a .tst value literal into an unsigned bit pattern of ``width``."""
    s = text.strip()
    if not s:
        raise ScriptError('empty value')
    if s[0] == '%':
        if len(s) < 3:
            raise ScriptError('bad value literal: %r' % text)
        kind = s[1].upper()
        rest = s[2:]
        neg = rest.startswith('-')
        if neg:
            rest = rest[1:]
        try:
            if kind == 'B':
                v = int(rest, 2)
            elif kind == 'X':
                v = int(rest, 16)
            elif kind == 'D':
                v = int(rest, 10)
            else:
                raise ScriptError('unknown radix %%%s' % s[1])
        except ValueError:
            raise ScriptError('bad value literal: %r' % text)
        if neg:
            v = -v
    else:
        low = s.lower()
        if low in ('true',):
            v = 1
        elif low in ('false',):
            v = 0
        else:
            try:
                v = int(s, 10)
            except ValueError:
                raise ScriptError('bad value literal: %r' % text)
    if width is None:
        return v
    return v & ((1 << width) - 1)


# ---------------------------------------------------------------------------
# output-list columns
# ---------------------------------------------------------------------------

_SPEC_RE = re.compile(r'^(?P<name>.+?)%(?P<fmt>[BDXS])'
                      r'(?P<left>\d+)\.(?P<width>\d+)\.(?P<right>\d+)$',
                      re.I)


class Column:
    """One ``output-list`` entry, e.g. ``RAM[16384]%D2.6.2``."""

    __slots__ = ('spec', 'name', 'base', 'index', 'fmt',
                 'left', 'width', 'right')

    def __init__(self, spec, name, fmt, left, width, right):
        self.spec = spec
        self.name = name              # display name, e.g. 'RAM[16384]'
        self.fmt = fmt                # 'B' | 'D' | 'X' | 'S'
        self.left = left
        self.width = width
        self.right = right
        base, index = split_indexed(name)
        self.base = base              # 'RAM'
        self.index = index            # 16384, or None when un-indexed

    @property
    def total(self):
        return self.left + self.width + self.right

    def __repr__(self):
        return 'Column(%r)' % (self.spec,)


_INDEX_RE = re.compile(r'^([A-Za-z_][\w.]*)\s*\[\s*(\d*)\s*\]$')


def split_indexed(name):
    """``RAM[3]`` -> ``('RAM', 3)``; ``PC[]`` -> ``('PC', 0)``; ``pc`` -> ``('pc', None)``."""
    m = _INDEX_RE.match(name.strip())
    if not m:
        return name.strip(), None
    return m.group(1), int(m.group(2)) if m.group(2) else 0


def parse_output_spec(token):
    m = _SPEC_RE.match(token.strip())
    if not m:
        # No format given: the official simulator falls back to the pin's
        # default.  Decimal in a 6-wide field matches every script in this
        # repository that omits it.
        if '%' in token:
            raise ScriptError('bad output-list spec: %r' % token)
        return Column(token.strip(), token.strip(), 'D', 1, 6, 1)
    return Column(token.strip(), m.group('name'), m.group('fmt').upper(),
                  int(m.group('left')), int(m.group('width')),
                  int(m.group('right')))


def parse_output_list(tokens):
    return [parse_output_spec(t) for t in tokens]


def header_cell(col):
    """Name centred in ``col.total``, extra space biased to the RIGHT."""
    width = col.total
    name = col.name
    if len(name) >= width:
        return name[:width]
    pad = width - len(name)
    left = pad // 2
    return ' ' * left + name + ' ' * (pad - left)


def header_line(cols):
    return '|' + '|'.join(header_cell(c) for c in cols) + '|'


def format_cell(col, value, bits=16):
    """Render one column.  ``value`` is an unsigned bit pattern (or a str for %S)."""
    fmt = col.fmt
    w = col.width
    if fmt == 'S':
        body = str(value).ljust(w)
    elif fmt == 'B':
        mask = (1 << w) - 1 if w else 0
        body = format(int(value) & mask, '0%db' % w) if w else ''
    elif fmt == 'X':
        digits = int(math.ceil(w))
        mask = (1 << (4 * digits)) - 1 if digits else 0
        body = format(int(value) & mask, '0%dX' % digits) if digits else ''
    elif fmt == 'D':
        v = int(value)
        if bits and v >= (1 << (bits - 1)):
            v -= (1 << bits)
        body = str(v).rjust(w)
    else:
        raise ScriptError('unknown format %%%s' % fmt)
    return ' ' * col.left + body + ' ' * col.right


def render_line(cols, values, bits=None):
    """``values``/``bits`` are parallel to ``cols``; ``bits`` defaults to 16."""
    cells = []
    for i, col in enumerate(cols):
        b = 16 if bits is None else bits[i]
        cells.append(format_cell(col, values[i], b))
    return '|' + '|'.join(cells) + '|'


# ---------------------------------------------------------------------------
# .cmp comparison
# ---------------------------------------------------------------------------

def load_cmp(path):
    """Read a .cmp file into a list of lines.

    Only line endings are normalised (a trailing ``\\r`` is dropped); no other
    whitespace is touched, since column padding is significant.
    """
    with open(path, 'rb') as fh:
        raw = fh.read()
    text = raw.decode('utf-8', 'replace')
    lines = text.split('\n')
    lines = [ln[:-1] if ln.endswith('\r') else ln for ln in lines]
    while lines and lines[-1] == '':
        lines.pop()
    return lines


def line_matches(actual, expected):
    """Compare one line; ``'*'`` in ``expected`` matches any single character."""
    if len(actual) != len(expected):
        return False
    for a, e in zip(actual, expected):
        if e != '*' and a != e:
            return False
    return True


def first_mismatch(actual_lines, expected_lines):
    """Return ``(lineno, actual, expected)`` for the first difference, else None.

    ``lineno`` is 1-based.  Missing lines are reported as ``None``.
    """
    n = max(len(actual_lines), len(expected_lines))
    for i in range(n):
        a = actual_lines[i] if i < len(actual_lines) else None
        e = expected_lines[i] if i < len(expected_lines) else None
        if a is None or e is None or not line_matches(a, e):
            return i + 1, a, e
    return None

"""A complete Hack assembler (nand2tetris project 06).

Public API
----------
``assemble_file(path) -> list[int]``      16-bit words
``assemble_text(text) -> list[int]``
``assemble_lines(lines) -> list[int]``
``to_binary_lines(words) -> list[str]``   '0'/'1' strings, 16 chars each
``load_hack(path) -> list[int]``          read a pre-assembled .hack file
``load_program(path) -> list[int]``       dispatch on .asm / .hack
``is_stub(path) -> bool``                 '// TODO: implement' placeholder

CLI: ``python3 assembler.py Prog.asm [-o Prog.hack]``
"""

import os
import re
import sys

__all__ = [
    'AsmError', 'StubProgram', 'assemble_file', 'assemble_text',
    'assemble_lines', 'to_binary_lines', 'load_hack', 'load_program',
    'is_stub', 'PREDEFINED', 'COMP', 'DEST', 'JUMP',
]


class AsmError(Exception):
    pass


class StubProgram(AsmError):
    """Raised when a source file is still a ``// TODO: implement`` stub."""


# ---------------------------------------------------------------------------
# symbol / mnemonic tables
# ---------------------------------------------------------------------------

PREDEFINED = {
    'SP': 0, 'LCL': 1, 'ARG': 2, 'THIS': 3, 'THAT': 4,
    'SCREEN': 16384, 'KBD': 24576,
}
for _i in range(16):
    PREDEFINED['R%d' % _i] = _i
del _i

# comp -> 7 bits (a c1 c2 c3 c4 c5 c6), canonical table from the book.
COMP = {
    '0':   0b0101010,
    '1':   0b0111111,
    '-1':  0b0111010,
    'D':   0b0001100,
    'A':   0b0110000,
    '!D':  0b0001101,
    '!A':  0b0110001,
    '-D':  0b0001111,
    '-A':  0b0110011,
    'D+1': 0b0011111,
    'A+1': 0b0110111,
    'D-1': 0b0001110,
    'A-1': 0b0110010,
    'D+A': 0b0000010,
    'D-A': 0b0010011,
    'A-D': 0b0000111,
    'D&A': 0b0000000,
    'D|A': 0b0010101,
}
# the a=1 mirror of every A-form: same c bits, a set, A replaced by M
for _k, _v in list(COMP.items()):
    if 'A' in _k:
        COMP[_k.replace('A', 'M')] = _v | 0b1000000
del _k, _v

# Commutative / trivially-equivalent spellings the official assembler also
# accepts (A+D, M+D, 1+D, A&D, A|D, ...).
for _k, _v in list(COMP.items()):
    for _op in ('+', '&', '|'):
        if _op in _k:
            _l, _r = _k.split(_op, 1)
            _mirror = _r + _op + _l
            if _mirror not in COMP:
                COMP[_mirror] = _v
del _k, _v

JUMP = {
    '': 0b000, 'JGT': 0b001, 'JEQ': 0b010, 'JGE': 0b011,
    'JLT': 0b100, 'JLE': 0b101, 'JNE': 0b110, 'JMP': 0b111,
}

# dest is the set of target chars; bit 4 = A, bit 2 = D, bit 1 = M.
_DEST_BIT = {'A': 0b100, 'D': 0b010, 'M': 0b001}
DEST = {'': 0}


def _dest_bits(text):
    if text in DEST:
        return DEST[text]
    bits = 0
    for ch in text:
        if ch not in _DEST_BIT:
            raise AsmError('bad dest mnemonic: %r' % text)
        b = _DEST_BIT[ch]
        if bits & b:
            raise AsmError('repeated dest register in %r' % text)
        bits |= b
    DEST[text] = bits
    return bits


for _d in ('M', 'D', 'MD', 'DM', 'A', 'AM', 'MA', 'AD', 'DA',
           'AMD', 'ADM', 'MAD', 'MDA', 'DAM', 'DMA'):
    _dest_bits(_d)
del _d


# ---------------------------------------------------------------------------
# lexing
# ---------------------------------------------------------------------------

_WS_RE = re.compile(r'\s+')
_SYMBOL_RE = re.compile(r'^[A-Za-z_.$:][\w.$:]*$')


def _clean_lines(lines):
    """Strip comments and all whitespace; return [(lineno, text), ...]."""
    out = []
    for no, raw in enumerate(lines, 1):
        text = raw
        cut = text.find('//')
        if cut >= 0:
            text = text[:cut]
        text = _WS_RE.sub('', text)
        if text:
            out.append((no, text))
    return out


def is_stub(path):
    """True when ``path`` holds no instructions (a ``// TODO: implement`` stub)."""
    with open(path, 'r', errors='replace') as fh:
        lines = fh.read().splitlines()
    return not _clean_lines(lines)


# ---------------------------------------------------------------------------
# assembling
# ---------------------------------------------------------------------------

def _parse_c_instruction(text, lineno):
    dest_txt = ''
    rest = text
    if '=' in rest:
        dest_txt, rest = rest.split('=', 1)
        if '=' in rest:
            raise AsmError('line %d: multiple "=" in %r' % (lineno, text))
    jump_txt = ''
    if ';' in rest:
        rest, jump_txt = rest.split(';', 1)
        if ';' in jump_txt:
            raise AsmError('line %d: multiple ";" in %r' % (lineno, text))
    comp_txt = rest
    if comp_txt not in COMP:
        raise AsmError('line %d: unknown comp %r in %r'
                       % (lineno, comp_txt, text))
    ju = jump_txt.upper()
    if ju not in JUMP:
        raise AsmError('line %d: unknown jump %r in %r'
                       % (lineno, jump_txt, text))
    try:
        dest = _dest_bits(dest_txt)
    except AsmError as exc:
        raise AsmError('line %d: %s in %r' % (lineno, exc, text))
    return 0b111 << 13 | COMP[comp_txt] << 6 | dest << 3 | JUMP[ju]


def assemble_lines(lines, source='<asm>'):
    """Two-pass assembly of an iterable of raw source lines."""
    cleaned = _clean_lines(list(lines))
    if not cleaned:
        raise StubProgram('%s: no instructions (stub?)' % source)

    symbols = dict(PREDEFINED)

    # pass 1: labels
    addr = 0
    program = []                      # [(lineno, text), ...] instructions only
    for lineno, text in cleaned:
        if text.startswith('('):
            if not text.endswith(')'):
                raise AsmError('%s line %d: bad label %r'
                               % (source, lineno, text))
            name = text[1:-1]
            if not _SYMBOL_RE.match(name):
                raise AsmError('%s line %d: bad label name %r'
                               % (source, lineno, name))
            if name in symbols and name not in PREDEFINED:
                raise AsmError('%s line %d: duplicate label %r'
                               % (source, lineno, name))
            symbols[name] = addr
            continue
        program.append((lineno, text))
        addr += 1

    # pass 2: instructions, allocating variables from 16 upward
    next_var = 16
    words = []
    for lineno, text in program:
        if text.startswith('@'):
            arg = text[1:]
            if not arg:
                raise AsmError('%s line %d: empty @' % (source, lineno))
            if arg.isdigit():
                value = int(arg, 10)
                if value > 32767:
                    raise AsmError('%s line %d: address %d out of range'
                                   % (source, lineno, value))
            else:
                if not _SYMBOL_RE.match(arg):
                    raise AsmError('%s line %d: bad symbol %r'
                                   % (source, lineno, arg))
                if arg not in symbols:
                    symbols[arg] = next_var
                    next_var += 1
                    if next_var > 16384:
                        raise AsmError('%s line %d: out of variable space'
                                       % (source, lineno))
                value = symbols[arg]
            words.append(value & 0x7FFF)
        else:
            try:
                words.append(_parse_c_instruction(text, lineno))
            except AsmError as exc:
                raise AsmError('%s %s' % (source, str(exc)))
    return words


def assemble_text(text, source='<asm>'):
    return assemble_lines(text.splitlines(), source)


def assemble_file(path):
    """Assemble ``path`` into a list of 16-bit ints."""
    with open(path, 'r', errors='replace') as fh:
        text = fh.read()
    return assemble_text(text, os.path.basename(path))


def to_binary_lines(words):
    return [format(w & 0xFFFF, '016b') for w in words]


# ---------------------------------------------------------------------------
# .hack loading
# ---------------------------------------------------------------------------

def load_hack(path):
    """Read a ``.hack`` file (16 '0'/'1' chars per line) into ints."""
    words = []
    with open(path, 'r', errors='replace') as fh:
        for no, raw in enumerate(fh, 1):
            line = raw.strip()
            if not line:
                continue
            if len(line) != 16 or set(line) - {'0', '1'}:
                raise AsmError('%s line %d: not a 16-bit binary word: %r'
                               % (path, no, line))
            words.append(int(line, 2))
    if not words:
        raise StubProgram('%s: empty .hack file' % path)
    return words


def load_program(path):
    """Load a program from ``.asm`` or ``.hack``."""
    ext = os.path.splitext(path)[1].lower()
    if ext == '.hack':
        return load_hack(path)
    return assemble_file(path)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    out = None
    if '-o' in argv:
        i = argv.index('-o')
        try:
            out = argv[i + 1]
        except IndexError:
            sys.stderr.write('-o needs a path\n')
            return 2
        del argv[i:i + 2]
    if len(argv) != 1:
        sys.stderr.write('usage: assembler.py Prog.asm [-o Prog.hack]\n')
        return 2
    try:
        words = assemble_file(argv[0])
    except AsmError as exc:
        sys.stderr.write('error: %s\n' % exc)
        return 1
    text = '\n'.join(to_binary_lines(words)) + '\n'
    if out:
        with open(out, 'w') as fh:
            fh.write(text)
    else:
        sys.stdout.write(text)
    return 0


if __name__ == '__main__':
    sys.exit(main())

