#!/usr/bin/env python3
"""Run nand2tetris *assembly* .tst scripts (projects/04) on the Hack emulator.

These scripts never touch HDL: the official flow runs them in the CPUEmulator,
so this runner pairs ``agent_tests/hack/assembler.py`` with
``agent_tests/hack/emulator.py``.  Script parsing, output formatting and
``.cmp`` comparison all come from ``agent_tests/common_fmt.py``, which the HDL
runner shares.

Usage
-----
    python3 agent_tests/run_asm_tests.py projects/04/mult/Mult.tst \
                                         projects/04/fill/FillAutomatic.tst

Options
-------
    --scratch DIR        where .out files go (never inside projects/)
    --prog PATH          replace the program loaded by every script
    --prog NAME=PATH     replace only the program loaded as NAME
    --repeat-cap N       iteration cap for ``repeat { ... }`` (unbounded)
    --while-cap N        iteration cap for ``while ... { ... }``
    -q / -v              quieter / more verbose
"""

import argparse
import os
import sys
import time

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if _ROOT not in sys.path:
    sys.path.insert(0, _ROOT)

from agent_tests import common_fmt as fmt                       # noqa: E402
from agent_tests.hack import assembler as asm                   # noqa: E402
from agent_tests.hack import emulator as emu                    # noqa: E402

DEFAULT_SCRATCH = os.path.join(_ROOT, 'agent_tests', '.out')
DEFAULT_REPEAT_CAP = 100000
DEFAULT_WHILE_CAP = 1000000


class TestFailure(Exception):
    """A comparison mismatch (the script itself ran fine)."""

    def __init__(self, lineno, actual, expected):
        self.lineno = lineno
        self.actual = actual
        self.expected = expected
        super().__init__('line %d mismatch' % lineno)


class Skip(Exception):
    """The script cannot run because the program under test is a stub."""


# ---------------------------------------------------------------------------

_RAM_ALIASES = ('ram', 'ram16k', 'memory')
_A_ALIASES = ('a', 'aregister')
_D_ALIASES = ('d', 'dregister')
_PC_ALIASES = ('pc', 'programcounter')


class AsmScriptRunner:
    """Executes one assembly .tst script."""

    def __init__(self, tst_path, scratch=DEFAULT_SCRATCH, prog_override=None,
                 repeat_cap=DEFAULT_REPEAT_CAP, while_cap=DEFAULT_WHILE_CAP,
                 verbose=False):
        self.tst_path = os.path.abspath(tst_path)
        self.dir = os.path.dirname(self.tst_path)
        self.scratch = os.path.abspath(scratch)
        self.prog_override = prog_override or {}
        self.repeat_cap = repeat_cap
        self.while_cap = while_cap
        self.verbose = verbose

        self.cpu = emu.CPU()
        self.loaded = None
        self.cols = []
        self.out_path = None
        self.cmp_lines = None
        self.out_lines = []
        self.n_output = 0
        self.header_written = False
        self.echo_text = ''
        self.time_n = 0
        self.time_half = False
        self.steps = 0

    # -- helpers ----------------------------------------------------------
    def _resolve(self, name):
        if os.path.isabs(name):
            return name
        return os.path.join(self.dir, name)

    def _program_path(self, name):
        base = os.path.basename(name)
        if base in self.prog_override:
            return self.prog_override[base]
        if '*' in self.prog_override:
            return self.prog_override['*']
        return self._resolve(name)

    def time_string(self):
        return '%d+' % self.time_n if self.time_half else '%d' % self.time_n

    # -- state access -----------------------------------------------------
    def read_state(self, base, index):
        b = base.lower()
        cpu = self.cpu
        if b == 'time':
            return self.time_string()
        if b in _RAM_ALIASES:
            return cpu.ram[index or 0]
        if b == 'screen':
            return cpu.ram[emu.SCREEN + (index or 0)]
        if b in ('keyboard', 'kbd'):
            return cpu.ram[emu.KBD]
        if b in _PC_ALIASES:
            return cpu.pc
        if b in _A_ALIASES:
            return cpu.a
        if b in _D_ALIASES:
            return cpu.d
        if b == 'rom' or b == 'rom32k':
            i = index or 0
            return cpu.rom[i] if i < len(cpu.rom) else 0
        raise fmt.ScriptError('unknown state reference %r' % base)

    def write_state(self, base, index, value):
        b = base.lower()
        cpu = self.cpu
        if b in _RAM_ALIASES:
            cpu.ram[index or 0] = value & 0xFFFF
        elif b == 'screen':
            cpu.ram[emu.SCREEN + (index or 0)] = value & 0xFFFF
        elif b in ('keyboard', 'kbd'):
            cpu.ram[emu.KBD] = value & 0xFFFF
        elif b in _PC_ALIASES:
            cpu.pc = value & 0x7FFF
        elif b in _A_ALIASES:
            cpu.a = value & 0xFFFF
        elif b in _D_ALIASES:
            cpu.d = value & 0xFFFF
        else:
            raise fmt.ScriptError('cannot set %r' % base)

    # -- clock ------------------------------------------------------------
    def do_tick(self):
        self.cpu.run(1)
        self.steps += 1
        self.time_half = True

    def do_tock(self):
        if self.time_half:
            self.time_n += 1
            self.time_half = False
        else:
            # a bare 'tock' still advances the emulator by one instruction
            self.cpu.run(1)
            self.steps += 1
            self.time_n += 1

    def do_ticktock(self, count=1):
        if count <= 0:
            return
        self.cpu.run(count)
        self.steps += count
        self.time_n += count
        self.time_half = False

    # -- output -----------------------------------------------------------
    def _emit(self, line):
        self.out_lines.append(line)
        if self.cmp_lines is not None:
            i = len(self.out_lines) - 1
            if i >= len(self.cmp_lines):
                raise TestFailure(i + 1, line, None)
            if not fmt.line_matches(line, self.cmp_lines[i]):
                raise TestFailure(i + 1, line, self.cmp_lines[i])

    def write_header(self):
        if self.header_written or not self.cols:
            return
        self.header_written = True
        self._emit(fmt.header_line(self.cols))

    def do_output(self):
        if not self.cols:
            return
        self.write_header()
        values = [self.read_state(c.base, c.index) for c in self.cols]
        self._emit(fmt.render_line(self.cols, values))
        self.n_output += 1

    # -- commands ---------------------------------------------------------
    def exec_cmd(self, cmd):
        words = cmd.words
        if not words:
            return
        name = words[0].lower()

        # "<ChipName> load <file>", e.g. "ROM32K load Add.hack"
        if len(words) >= 3 and words[1].lower() == 'load':
            name, words = 'load', ['load'] + words[2:]

        if name == 'load':
            if len(words) < 2:
                raise fmt.ScriptError('load needs a file name')
            src = words[1]
            path = self._program_path(src)
            if not os.path.exists(path):
                raise fmt.ScriptError('program not found: %s' % path)
            if path.lower().endswith('.asm') and asm.is_stub(path):
                raise Skip('%s is still a "// TODO: implement" stub'
                           % os.path.basename(path))
            try:
                self.cpu.load_program(path)
            except asm.StubProgram as exc:
                raise Skip(str(exc))
            self.loaded = path
            self.cpu.clear_ram()
            self.cpu.reset()
            self.time_n = 0
            self.time_half = False
        elif name == 'output-file':
            self.out_path = os.path.join(self.scratch, os.path.basename(words[1]))
        elif name == 'compare-to':
            self.cmp_lines = fmt.load_cmp(self._resolve(words[1]))
        elif name == 'output-list':
            self.cols = fmt.parse_output_list(words[1:])
            self.header_written = False
            self.write_header()
        elif name == 'set':
            if len(words) < 3:
                raise fmt.ScriptError('set needs a target and a value')
            base, index = fmt.split_indexed(words[1])
            self.write_state(base, index, fmt.parse_value(words[2]))
        elif name in ('eval', 'breakpoint', 'clear-breakpoints'):
            pass
        elif name == 'tick':
            self.do_tick()
        elif name == 'tock':
            self.do_tock()
        elif name == 'ticktock':
            self.do_ticktock(1)
        elif name == 'output':
            self.do_output()
        elif name == 'echo':
            self.echo_text = cmd.tokens[1].text if len(cmd.tokens) > 1 else ''
            if self.verbose:
                print('    echo: %s' % self.echo_text)
        elif name == 'clear-echo':
            self.echo_text = ''
        else:
            raise fmt.ScriptError('unknown command %r' % ' '.join(words))

    # -- blocks -----------------------------------------------------------
    @staticmethod
    def _pure_ticktock(body):
        """If ``body`` is only ticktock/eval commands, return how many ticks."""
        n = 0
        for node in body:
            if not isinstance(node, fmt.Cmd):
                return None
            nm = node.name
            if nm == 'ticktock':
                n += 1
            elif nm in ('eval', 'breakpoint'):
                continue
            else:
                return None
        return n

    def exec_nodes(self, nodes):
        for node in nodes:
            if isinstance(node, fmt.Cmd):
                self.exec_cmd(node)
            elif isinstance(node, fmt.Repeat):
                count = self.repeat_cap if node.count is None else node.count
                per = self._pure_ticktock(node.body)
                if per is not None:
                    # fast path: collapse the whole block into one run() call
                    self.do_ticktock(count * per)
                else:
                    for _ in range(count):
                        self.exec_nodes(node.body)
            elif isinstance(node, fmt.While):
                iters = 0
                while self.eval_cond(node):
                    self.exec_nodes(node.body)
                    iters += 1
                    if iters >= self.while_cap:
                        break
            else:
                raise fmt.ScriptError('unknown node %r' % (node,))

    def _operand(self, text):
        try:
            v = fmt.parse_value(text, width=None)
        except fmt.ScriptError:
            base, index = fmt.split_indexed(text)
            v = self.read_state(base, index)
        v = int(v) & 0xFFFF
        return v - 65536 if v > 32767 else v

    def eval_cond(self, node):
        lhs = self._operand(node.lhs)
        rhs = self._operand(node.rhs)
        op = node.op
        if op == '=':
            return lhs == rhs
        if op == '<>':
            return lhs != rhs
        if op == '<':
            return lhs < rhs
        if op == '>':
            return lhs > rhs
        if op == '<=':
            return lhs <= rhs
        if op == '>=':
            return lhs >= rhs
        raise fmt.ScriptError('unknown comparison %r' % op)

    # -- driver -----------------------------------------------------------
    def run(self):
        with open(self.tst_path, 'r', errors='replace') as fh:
            nodes = fmt.parse_script(fh.read())
        self.exec_nodes(nodes)
        return self.finish()

    def finish(self):
        if self.out_path:
            os.makedirs(os.path.dirname(self.out_path), exist_ok=True)
            with open(self.out_path, 'w', newline='\n') as fh:
                for line in self.out_lines:
                    fh.write(line + '\n')
        if self.cmp_lines is not None:
            diff = fmt.first_mismatch(self.out_lines, self.cmp_lines)
            if diff:
                raise TestFailure(*diff)
        return True


# ---------------------------------------------------------------------------

def run_one(path, args):
    runner = AsmScriptRunner(path, scratch=args.scratch,
                             prog_override=args.prog_map,
                             repeat_cap=args.repeat_cap,
                             while_cap=args.while_cap,
                             verbose=args.verbose)
    t0 = time.time()
    try:
        runner.run()
    except Skip as exc:
        return 'SKIP', 'stub: %s' % exc, runner, time.time() - t0
    except TestFailure as exc:
        detail = ('line %d\n      actual   : %r\n      expected : %r'
                  % (exc.lineno, exc.actual, exc.expected))
        return 'FAIL', detail, runner, time.time() - t0
    except (fmt.ScriptError, asm.AsmError, OSError) as exc:
        return 'ERROR', '%s: %s' % (type(exc).__name__, exc), runner, \
            time.time() - t0
    return 'PASS', '%d output line(s), %d instructions' % (
        runner.n_output, runner.steps), runner, time.time() - t0


def parse_args(argv):
    p = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    p.add_argument('scripts', nargs='+', help='.tst files to run')
    p.add_argument('--scratch', default=DEFAULT_SCRATCH,
                   help='directory for .out files (default: %(default)s)')
    p.add_argument('--prog', action='append', default=[],
                   help='PATH or NAME=PATH program substitution')
    p.add_argument('--repeat-cap', type=int, default=DEFAULT_REPEAT_CAP)
    p.add_argument('--while-cap', type=int, default=DEFAULT_WHILE_CAP)
    p.add_argument('-v', '--verbose', action='store_true')
    p.add_argument('-q', '--quiet', action='store_true')
    args = p.parse_args(argv)
    mapping = {}
    for item in args.prog:
        if '=' in item:
            k, _, v = item.partition('=')
            mapping[os.path.basename(k)] = os.path.abspath(v)
        else:
            mapping['*'] = os.path.abspath(item)
    args.prog_map = mapping
    if args.scratch and 'projects' in os.path.abspath(args.scratch).split(os.sep):
        p.error('refusing to write .out files inside projects/')
    return args


def main(argv=None):
    args = parse_args(list(sys.argv[1:] if argv is None else argv))
    failures = 0
    for path in args.scripts:
        status, detail, runner, secs = run_one(path, args)
        if status != 'PASS':
            failures += 1 if status != 'SKIP' else 0
        rel = os.path.relpath(os.path.abspath(path), _ROOT)
        if not args.quiet or status != 'PASS':
            print('%-5s %-42s (%.2fs)  %s' % (status, rel, secs, detail))
    return 1 if failures else 0


if __name__ == '__main__':
    sys.exit(main())

